import{_ as c,C as l,c as a,o as p,j as e,G as i,a3 as d,a as s,w as r}from"./chunks/framework.Dhzub2q0.js";const y=JSON.parse('{"title":"我们在您身边","description":"","frontmatter":{"prev":false,"next":false},"headers":[],"relativePath":"support/wearebyyourside.md","filePath":"support/wearebyyourside.md"}'),n={name:"support/wearebyyourside.md"};function u(m,o,b,_,f,k){const t=l("cw");return p(),a("div",null,[o[1]||(o[1]=e("h1",{id:"我们在您身边",tabindex:"-1"},[s("我们在您身边 "),e("a",{class:"header-anchor",href:"#我们在您身边","aria-label":'Permalink to "我们在您身边"'},"​")],-1)),o[2]||(o[2]=e("blockquote",null,[e("p",null,"作为一个看不见的朋友，我们一直在您身边。(￣y▽,￣)╭")],-1)),i(t,null,{default:r(()=>o[0]||(o[0]=[s("自杀",-1)])),_:1,__:[0]}),o[3]||(o[3]=d('<p>那些一个人走过的路和哀叹的夜，总是放大生活中的失落与无助，让人陷入无尽的忧郁黑洞，甚至想要放弃自己的生命。黑暗像潮水漫过脚踝时，连呼吸都带着沉重的回音，仿佛全世界都调成了静音模式，只有自己的心跳在空荡里反复碰壁。​</p><p>但是，朋友，你知道吗？生活中同样也有一些细小的幸福因子等待你去发现。清晨窗台积着的薄霜，在阳光下会化成星星点点的光；街角面包店飘出的甜香，藏着某个人早起揉面时的体温；甚至手机里偶然弹出的旧照片，都藏着曾经让你笑出声的瞬间。​</p><p>就像现在，你指尖划过的这行字，也是咱们带着小心思写下的。我们在想，该用怎样的温度，才能让你知道，那些看似走不完的隧道，其实早有微光在尽头等你。累了就靠在墙边歇一歇，雨停了总会有月亮爬上来，而我们会像路灯一样，在你看得见或看不见的地方，一直亮着。​</p><p>你不必急着逼自己好起来，就像冬天的树不必强迫自己开花。允许自己暂时停在原地，允许眼泪慢慢流，允许心里的雾慢慢散。等你愿意挪步时会发现，路上早有落叶铺成柔软的毯，风里带着远处传来的歌，而那些悄悄牵挂你的人，一直都在。也许现在你眼前的世界满是乌云，模糊不清，但请记住，你的存在本身，便是这个世界独一无二、无比珍贵的诗篇。</p><hr><div class="info custom-block"><p class="custom-block-title">沫狐奶昔 CimiMoly <code>室长</code> <code>开发组</code></p><p>也许你正在寻找某些事物的答案，关于自己所爱的一切——也许你还记得那盏在深夜等着你的小灯，也许你还记得自己好奇时发现的墙边那株嫩绿的小草，也许你还记得放学路上的铃铛，和自己投喂过的小猫，也许你还记得那天梦里牵起过的手，也许你还记得某一个清晨轻轻拂过自己的微风，和轻洒在身上的暖暖阳光......<br> 无数回忆与期待，都是你在心里种下的繁星朵朵。夜再黑，也阻挡不住星星的光亮，而你的心里，正是那无数星星居住的地方。曾经在日记本写下的诗句，待到春意盎然之时，定会随着微风，随着飞舞的蝴蝶，随着花瓣一起，织起满满希望的未来。</p></div><div class="info custom-block"><p class="custom-block-title">神楽悠笙 <code>开发组</code></p><p>在某个你不知道的房间里，一盏灯正亮着，灯下的人可能刚泡好一杯温热的茶，或者只是望着窗外发呆。这盏灯，没有特别的目的，它亮着，只是因为知道有人在某个地方可能需要一点点光的方向感。 就像此刻你手机、电脑屏幕的光，映着你的脸庞。<br> 我们无法替你走过黑夜，但我们相信，总有一些光亮，会在你甚至没有抬头寻找时，就落在你脚边。我们的守望，就是相信这些微光的存在，并提醒你：它们会来。</p></div><div class="info custom-block"><p class="custom-block-title">Thallium_Ash【铊尘】 <code>开发组</code></p><p>人生的道路很漫长，这条路上的风景很美，令人流连忘返。这条道路有时候或许很蜿蜒曲折、荆棘丛生亦或是狂风呼啸、雷雨交加。但是我亲爱的朋友，当你回望你走过的路，你会发现，它金灿灿的，宛若星河。而它的周围环绕的是四时风景，是安闲恬淡。<br> 我的朋友，人生不止眼前的苟且，还有那流觞曲水的诗词和远方美丽的山川田野。而我如你身边的清风，如影随形，为你呐喊喝彩。</p></div><div class="info custom-block"><p class="custom-block-title">Yuyudifiesh <code>开发组</code></p><p>当你在书页间停顿，或许正有片叶子从某棵不知名的树上飘落；当你凝望窗外，远处某扇窗内的绿植，可能正将新生的叶尖探向薄雾般的晨光。<br> 这些瞬间没有目的，不为谁刻意发生，它们只是世界平稳呼吸时的自然脉动。如同此刻指尖触碰屏幕光亮映在瞳孔里的微小星点——它们不声张，只是存在着，成为当下的感知。前路的跋涉终须独自完成，心头的重担也需亲自安放。但总有些时刻，某种未预约的暖意会悄然降临。<br> 世界自有它沉默的温柔。当目光愿意停留在一片叶的飘零，一株草的伸展，一杯茶渐散的温度，某种笃信便会在心底自然生长，黑暗的密度并非恒定，光总在寻找需要它的缝隙。而你，或许比想象中更早站在了光的路径上。</p></div><div class="info custom-block"><p class="custom-block-title">白菜 <code>开发组</code></p><p>我是白菜，一个习惯生活在现实边缘的人。或许你如同薛之谦的“动物世界”里的那样，感觉这个世界“优胜劣汰”，只能“自舔伤疤”。但是当你抽出时间看到这句话的时候，我只想告诉你：“蔑视那些来自生活的傲慢与偏见吧。时间的尘埃会把过去的伤痕湮灭。”我是我，但有时候我又非我，但是我就是我。恶意轻轻的把我们埋在土里，那我们就悄悄等待破土成蝶的那天。</p></div><div class="info custom-block"><p class="custom-block-title">池文</p><p>“每一个明确走在晴天朗照中的人，很可能正在心魂的黑暗与迷茫中挣扎。”愿你在这段经历中守护内心的自己，希望与你同在。尽管生活窘迫，但我们依然可以在不经意间传来的阵阵花香中，找到期待和欢乐的滋味。愿你能拥有更多的幸福，愿你的生命之树在感受阳光的温暖，绿叶的常青之时，能够恣意生长。</p></div>',11))])}const w=c(n,[["render",u]]);export{y as __pageData,w as default};
